option.value:
/* ===== ROOT ===== */


:root {
    --sidebar-bg: #04163f;
    --sidebar-muted: #9fb5de;
    --sidebar-active: #1f2f50;
    --surface: #f4f7fb;
    --card: #ffffff;
    --line: #dbe2ec;
    --line-strong: #c9d2e1;
    --text: #0f172a;
    --muted: #6b7280;
    --primary: #1e40af;
}

* {
    box-sizing: border-box;
}

.sr-only {
    position: absolute;
    width: 1px;
    height: 1px;
    padding: 0;
    margin: -1px;
    overflow: visible;
    clip: rect(0, 0, 0, 0);
    border: 0;
}

body {
    margin: 0;
    font-family: "Segoe UI", Arial, Helvetica, sans-serif;
    color: var(--text);
    background: #eceff4;
}

.page-layout {
    min-height: 100vh;
    display: grid;
    grid-template-columns: 250px minmax(0, 1fr);
}

.sidebar {
    background: #00558b;
    color: #fff;
    display: flex;
    flex-direction: column;
    border-right: 1px solid #0b2558;
    position: sticky;
    top: 0;              /*  bắt buộc */
    height: 100vh;       /* để full chiều cao */
    align-self: start;   /* fix bug grid */
}

.brand-block {
    display: flex;
    flex-direction: column;
    align-items: center;
    padding: 22px 16px 18px;
    border-bottom: 1px solid #9aa0af;
}

.brand-logo {
    width: 118px;
    height: 150px;
    object-fit: cover;
    margin-bottom: 14px;
}


.student-info {
    width: 100%;
    text-align: left;
    display: flex;
    align-items: center;
    gap: 10px;
    margin-top: 8px;
    padding-top: 12px;
    position: relative;
}

.student-info::before {
    content: "";
    position: absolute;
    top: 0;
    left: -16px;
    right: -16px;
    border-top: 1px solid #9aa0af;
}

.avatar {
    width: 42px;
    height: 42px;
    border-radius: 50%;
    object-fit: cover;
    border: 2px solid rgba(255, 255, 255, 0.2);
    background: rgba(255, 255, 255, 0.08);
}

.student-info p {
    margin: 2px 0;
    font-size: 15px;
    color: var(--sidebar-muted);
}

.student-name {
    color: #f5f8ff !important;
    font-weight: 700;
    font-size: 16px;
}

.student-id {
    color: #d7e4ff !important;
}

.sidebar-nav {
    margin-top: 16px;
    display: flex;
    flex-direction: column;
    gap: 6px;
    padding: 0 12px;
}

.nav-item {
    display: flex;
    align-items: center;
    gap: 10px;
    color: #d7e4ff;
    text-decoration: none;
    padding: 10px 12px;
    border-radius: 10px;
    font-size: 15px;
    letter-spacing: 0.3px;    font-weight: 600;
    border: 1px solid transparent;
    transition: background 0.2s ease, border-color 0.2s ease;
}

.badge-count {
  margin-left: auto;
  min-width: 20px;
  height: 20px;
  padding: 0 6px;
  border-radius: 999px;
  background: #ef233c;
  color: #ffffff;
  font-size: 12px;
  font-weight: 700;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  line-height: 1;
}

.nav-icon {
    filter: grayscale(100%) brightness(1.5);
    width: 24px;
    height: 24px;
    border-radius: 7px;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    background: rgba(255, 255, 255, 0.08);
    font-size: 12px;
}

.nav-item:hover,
.nav-item.active {
    background: var(--sidebar-active);
    border-color: rgba(159, 181, 222, 0.35);
}

.logout-btn {
    margin-top: auto;
    display: block;
    color: #dce9ff;
    text-decoration: none;
    padding: 12px 20px;
    border-top: 1px solid #163364;
}

.main-content {
    padding: 0 10px 10px;
}

.main-header {
    margin-bottom: 10px;

    border-top: 0;
    /*background: #ffffff;*/
}

.school-title {
    margin: 0;
    font-size: 20px;
    font-weight: 700;
    color: #ababab;
    letter-spacing: 0.3px;
}

.main-header-top {
    background: #00558b;
    border-top: 3px solid #0c79b4;
    padding: 5px 32px;
}

.main-header-bottom {
    min-height: 58px;
    border-top: 1px solid #b8bec8;
    border-bottom: 2px solid #ccc;
    padding: 22px 0 0 5px;
}


.page-tab {
    margin: 0;
    position: relative;
    display: inline-flex;
    align-items: center;
    background: #00558b;
    color: #ffffff;
    font-size: 20px;
    font-weight: 700;
    line-height: 1;
    padding: 5px 22px;
    letter-spacing: 0.3px;
}

.page-tab::after {
    content: "";
    position: absolute;
    top: 0;
    right: -20px;

    width: 0;
    height: 0;

    border-bottom: 28px solid #7d7d7d; /*  đổi ở đây */
    border-right: 20px solid transparent;
}


.history-panel {
  min-height: calc(100vh - 20px);
  border-radius: 12px;
  display: flex;
  flex-direction: column;
  padding: 10px;
}

.toolbar {
  display: flex;
  gap: 6px;
  padding: 6px;
  border-radius: 12px;
}

.search-input,
.filter-group select {
  background: #fff;
  color: var(--text);
  border: 1px solid var(--line-strong);
  border-radius: 8px;
  height: 34px;
  padding: 0 10px;
  font-size: 14px;
}

.search-input {
  flex: 1;
}

.filter-group {
  display: flex;
  gap: 8px;
}

.filter-btn {
  height: 34px;
  border-radius: 8px;
  border: 1px solid #cbd5e1;
  background: #fff;
  color: #334155;
  font-size: 14px;
  font-weight: 600;
  padding: 0 10px;
  text-decoration: none;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
}

.filter-btn.apply {
  border-color: #2563eb;
  background: #2563eb;
  color: #fff;
}

.filter-btn.reset {
  border-color: #cbd5e1;
  background: #f8fafc;
}

.feedback-grid {
  flex: 1;
  margin-top: 10px;
  border: 1px solid var(--line-strong);
  border-radius: 12px;
  background: #f8fafc;
  padding: 12px;
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  grid-auto-rows: max-content;
  align-content: start;
  align-items: start;
  gap: 12px;
  overflow-y: auto;
}

.feedback-card {
  border: 1px solid var(--line);
  border-radius: 12px;
  background: var(--card);
  min-height: 220px;
  padding: 10px 0 0;
  display: flex;
  flex-direction: column;
  gap: 8px;
  overflow: hidden;
}

.card-head {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 8px;
  padding: 0 12px;
}

.status-pill {
  display: inline-flex;
  align-items: center;
  border-radius: 999px;
  padding: 3px 9px;
  font-size: 11px;
  font-weight: 700;
  border: 1px solid #d5dbe5;
  background: #eef2f7;
  color: #475569;
}

.status-pill.done {
  color: #0f766e;
  background: #dcfce7;
  border-color: #86efac;
}

.status-pill.processing {
  color: #1d4ed8;
  background: #dbeafe;
  border-color: #93c5fd;
}

.status-pill.waiting {
  color: #b45309;
  background: #ffedd5;
  border-color: #fdba74;
}


.status-pill.pending {
  color: #b45309;
  background: #ffedd5;
  border-color: #fdba74;
}

.status-pill.forwarding {
  color: #6b21a8;
  background: #f3e8ff;
  border-color: #e9d5ff;
}

.status-pill.approved {
  color: #1d4ed8;
  background: #dbeafe;
  border-color: #93c5fd;
}

.status-pill.rejected {
  color: #991b1b;
  background: #fee2e2;
  border-color: #fecaca;
}
.request-subject {
  margin: 0;
  padding: 0 12px;
  font-size: 16px;
  line-height: 1.2;
}

.request-description {
  margin: 0;
  color: #475569;
  line-height: 1.4;
  display: -webkit-box;
  -webkit-line-clamp: 3;
  -webkit-box-orient: vertical;
  overflow: hidden;
}

.request-meta-group {
  display: flex;
  flex-direction: column;
  gap: 4px;
  padding: 0 12px;
}

.request-meta {
  margin: 0;
  font-size: 12px;
  color: #475569;
  line-height: 1.4;
}

.request-chip {
  display: flex;
  align-items: center;
  gap: 8px;
  min-height: 28px;
  padding: 0 10px;
  border-radius: 8px;
  background: #eef2f7;
  color: #334155;
    font-size: 12.5px;
}

.meta-icon {
  font-size: 1rem;
  opacity: 0.5;
  vertical-align: middle;
  margin-right: 6px;
  filter: grayscale(1); /* Làm icon tiệp với màu chữ để sang hơn */
}

.card-footer {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-top: auto;
  border-top: 1px solid #e2e8f0;
  padding: 8px 12px;
}

.detail-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 4px;
  padding: 3px 6px;
  border-radius: 6px;
  border: 1px solid transparent;
  color: #1d4ed8;
  text-decoration: none;
  font-weight: 600;
  font-size: 12px;
}

.detail-btn::after {
  content: ">";
  font-size: 12px;
}

.detail-btn:hover {
  background: #eff6ff;
  border-color: #bfdbfe;
}

.request-date {
  color: #8ba0bd;
  font-size: 12px;
}

.request-detail {
  margin-top: 12px;
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.detail-header {
  display: flex;
}

.back-link {
  text-decoration: none;
  color: #1d4ed8;
  font-weight: 600;
}

.detail-top-card {
  border: 1px solid var(--line);
  border-radius: 12px;
  background: #fff;
  padding: 12px;
}

.detail-top-card h2 {
  margin: 0 0 12px;
    font-size: 18px;
}

.detail-top-card h3 {
  margin: 14px 0 8px;
}

.detail-meta {
  display: flex;
  gap: 8px;
  flex-wrap: wrap;
}

.detail-meta-row {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 10px;
  flex-wrap: wrap;
}

.forum-post-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  border: 1px solid #bfdbfe;
  background: #eff6ff;
  color: #1d4ed8;
  text-decoration: none;
  border-radius: 8px;
  padding: 6px 10px;
  font-size: 13px;
  font-weight: 700;
  white-space: nowrap;
}

.forum-post-btn:hover {
  background: #dbeafe;
}

.meta-chip {
  display: inline-flex;
  align-items: center;
  border-radius: 999px;
  padding: 2px 8px;
  border: 1px solid #d5dbe5;
  background: #f8fafc;
  color: #475569;
  font-size: 11px;
  font-weight: 600;
}

.meta-chip.mode-chip {
  font-weight: 700;
}

.meta-chip.mode-public {
  color: #1d4ed8;
  background: #dbeafe;
  border-color: #93c5fd;
}

.meta-chip.mode-department {
  color: #0f766e;
  background: #ecfeff;
  border-color: #67e8f9;
}

.meta-chip.time-chip {
  color: #334155;
  background: #f1f5f9;
  border-color: #cbd5e1;
}

.meta-chip.dept-chip {
  color: #92400e;
  background: #fef3c7;
  border-color: #fcd34d;
}

.detail-description {
  margin: 0;
  color: #334155;
  line-height: 1.6;
    font-size: 14px;
}

.detail-bottom-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 12px;
}

.detail-bottom-grid.single-panel {
  grid-template-columns: 1fr;
}

.detail-panel {
  border: 1px solid var(--line);
  border-radius: 12px;
  background: #fff;
  min-height: 300px;
  padding: 14px;
}

.detail-panel h3 {
  margin: 0 0 12px;
}

.timeline {
  position: relative;
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.timeline::before {
  content: "";
  position: absolute;
  left: 8px;
  top: 10px;
  bottom: 10px;
  width: 2px;
  background: #bfdbfe;
}

.timeline-item {
  position: relative;
  display: grid;
  grid-template-columns: 18px 1fr;
  gap: 10px;
  margin: 0;
}

.timeline-dot {
  width: 10px;
  height: 10px;
  border-radius: 50%;
  background: #3b82f6;
  margin-top: 8px;
}

.timeline-card {
  border: 1px solid #e2e8f0;
  border-radius: 10px;
  background: #f8fafc;
  padding: 10px;
}

.timeline-head {
  display: flex;
  justify-content: space-between;
  gap: 8px;
  align-items: center;
}

.timeline-head-left {
  display: flex;
  align-items: center;
  gap: 8px;
}

.timeline-type {
  display: inline-flex;
  align-items: center;
  border-radius: 999px;
  padding: 3px 8px;
  font-size: 11px;
  font-weight: 700;
  color: #334155;
  background: #e2e8f0;
}

.timeline-head time {
  color: #64748b;
  font-size: 12px;
}

.timeline-card p {
  margin: 8px 0 0;
  color: #334155;
}

.timeline-empty {
  border: 1px dashed #cbd5e1;
  border-radius: 10px;
  padding: 12px;
  color: #64748b;
  background: #f8fafc;
}

.chat-empty {
  min-height: 220px;
  border: 1px dashed #cbd5e1;
  border-radius: 10px;
  display: flex;
  align-items: center;
  justify-content: center;
  color: #64748b;
}

.chat-empty.compact {
  min-height: 140px;
  background: #ffffff;
}

.conversation-list {
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.conversation-item {
  width: 100%;
  border: 1px solid #d7dee8;
  border-radius: 14px;
  background: #ffffff;
  padding: 14px;
  display: grid;
  grid-template-columns: 42px minmax(0, 1fr) auto;
  gap: 12px;
  text-align: left;
  cursor: pointer;
}

.conversation-item:hover {
  border-color: #c4d4ef;
  box-shadow: 0 2px 10px rgba(59, 130, 246, 0.08);
}

.conversation-item.active {
  border-color: #3b82f6;
  box-shadow: 0 0 0 2px rgba(59, 130, 246, 0.15);
}

.conversation-item-icon {
  width: 38px;
  height: 38px;
  border-radius: 50%;
  background: #ecf1f8;
  color: #64748b;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  margin-top: 2px;
}

.conversation-item-main h4 {
  margin: 0;
  font-size: 32px;
  color: #0f172a;
  line-height: 1.25;
}

.conversation-item-main p {
  margin: 4px 0 8px;
  color: #64748b;
  font-size: 14px;
}

.conversation-item time {
  color: #7185ab;
  font-size: 13px;
  white-space: nowrap;
}

.conversation-open-pill {
  display: inline-flex;
  align-items: center;
  border-radius: 999px;
  padding: 3px 10px;
  background: #dcfce7;
  color: #166534;
  font-size: 12px;
  font-weight: 700;
}

.chat-drawer-backdrop {
  position: fixed;
  inset: 0;
  background: rgba(2, 6, 23, 0.32);
  z-index: 1200;
}

.chat-drawer {
  position: fixed;
  top: 0;
  right: -440px;
  width: 410px;
  max-width: 95vw;
  height: 100vh;
  border-left: 1px solid #e2e8f0;
  background: #ffffff;
  display: grid;
  grid-template-rows: auto 1fr auto;
  z-index: 1300;
  transition: right 0.25s ease;
}

.chat-drawer.open {
  right: 0;
}

.chat-drawer-header {
  padding: 16px;
  border-bottom: 1px solid #e2e8f0;
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
  gap: 10px;
}

.chat-drawer-header h3 {
  margin: 0;
  font-size: 34px;
  color: #0f172a;
  line-height: 1.3;
}

.chat-drawer-header p {
  margin: 6px 0 0;
  color: #64748b;
  font-size: 13px;
}

.chat-drawer-close {
  border: 0;
  background: transparent;
  color: #64748b;
  font-size: 24px;
  line-height: 1;
  cursor: pointer;
}

.chat-drawer-message-list {
  overflow-y: auto;
  padding: 14px;
  background: #f8fafc;
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.chat-drawer-compose {
  display: grid;
  grid-template-columns: 34px minmax(0, 1fr) 42px;
  gap: 8px;
  align-items: center;
  padding: 10px 12px;
  border-top: 1px solid #e2e8f0;
  background: #ffffff;
}

.chat-attach-btn {
  width: 34px;
  height: 34px;
  border: 1px solid #d7dee8;
  border-radius: 10px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  color: #64748b;
  cursor: pointer;
  user-select: none;
}

.chat-drawer-compose input[type="text"] {
  width: 100%;
  border: 1px solid #d7dee8;
  border-radius: 10px;
  height: 38px;
  padding: 0 10px;
}

.chat-send-btn {
  width: 42px;
  height: 38px;
  border: 0;
  border-radius: 10px;
  background: #3b82f6;
  color: #ffffff;
  cursor: pointer;
}

.chat-message {
  max-width: 85%;
  border: 1px solid #dbe6f3;
  border-radius: 10px;
  background: #ffffff;
  padding: 8px 10px;
}

.chat-message.mine {
  margin-left: auto;
  border-color: #bfdbfe;
  background: #eff6ff;
}

.chat-message-meta {
  display: flex;
  align-items: center;
  justify-content: flex-start;
  gap: 10px;
  font-size: 12px;
  color: #64748b;
}

.chat-message-text {
  margin: 6px 0 0;
  white-space: pre-wrap;
  line-height: 1.5;
  color: #1e293b;
}

.chat-attachment-list {
  margin: 8px 0 0;
  padding-left: 18px;
}

.chat-attachment-list a {
  color: #1d4ed8;
  text-decoration: none;
}

.chat-attachment-list a:hover {
  text-decoration: underline;
}

.chat-message-time {
  margin-top: 6px;
  font-size: 11px;
  color: rgba(100, 116, 139, 0.75);
}

.chat-message.mine .chat-message-time {
  color: rgba(59, 130, 246, 0.72);
}


.pagination {
  margin-top: 10px;
  display: flex;
  justify-content: center;
  align-items: center;
  gap: 10px;
  color: #243047;
  font-weight: 600;
    font-size: 13px;
}

.page-btn {
  width: 28px;
  height: 28px;
  border: 1px solid var(--line-strong);
  border-radius: 7px;
  color: #64748b;
  background: #fff;
  cursor: pointer;
  font-size: 12px;
  text-decoration: none;
  display: inline-flex;
  align-items: center;
  justify-content: center;

}

.page-btn:disabled {
  cursor: not-allowed;
  opacity: 0.55;
}

.empty-state {
  grid-column: 1 / -1;
  min-height: 220px;
  border: 2px dashed var(--line-strong);
  border-radius: 12px;
  background: #fff;
  display: flex;
  flex-direction: column;
  justify-content: center;
  align-items: center;
  text-align: center;
  color: #475569;
}

.empty-state h3 {
  margin: 0 0 8px;
  font-size: 18px;
  color: #0f172a;
}

.empty-state p {
  margin: 0;
}

.btn-action {
    display: inline-block;
    padding: 8px 16px;
    border-radius: 4px;
    text-decoration: none;
    font-size: 14px;
    cursor: pointer;
    border: 1px solid transparent;
}

/* nút sửa */
.btn-edit {
    background-color: #f0f0f0;
    color: #333;
    border-color: #ccc;
}

/* nút xóa */
.btn-delete {
    background-color: #d9534f;
    color: white;
    border-color: #d9534f;
}

/* hover đẹp hơn */
.btn-action:hover {
    opacity: 0.85;
}
@media (max-width: 980px) {
  .page-layout {
    grid-template-columns: 1fr;
  }

  .sidebar {
    flex-direction: row;
    align-items: center;
    gap: 10px;
    border-right: 0;
    border-bottom: 1px solid #163364;
    padding: 10px;
  }

  .brand-block {
    border-bottom: 0;
    padding: 0;
    flex-direction: row;
    gap: 10px;
  }

  .brand-logo {
    width: 56px;
    height: 56px;
    margin-bottom: 0;
  }

  .student-info {
    text-align: left;
    margin-top: 0;
    padding-top: 0;
  }

  .student-info::before {
    display: none;
  }

  .sidebar-nav {
    margin: 0;
    flex: 1;
    flex-direction: row;
    flex-wrap: wrap;
  }

  .main-header h1 {
    font-size: 22px;
  }

  .logout-btn {
    margin-top: 0;
    border-top: 0;
    padding: 10px 12px;
  }
}

@media (max-width: 680px) {
  .main-header-top {
    padding: 10px 12px;
  }

  .school-title {
    font-size: 20px;
  }

  .main-header-bottom {
    padding: 14px 0 0 12px;
    min-height: 62px;
  }

  .page-tab {
    font-size: 18px;
    padding: 10px 14px;
  }

  .page-tab::after {
    border-top-width: 19px;
    border-bottom-width: 19px;
  }

  .toolbar {
    flex-direction: column;
  }

  .filter-group {
    flex-direction: column;
  }

  .filter-btn {
    width: 100%;
  }

  .feedback-grid {
    grid-template-columns: 1fr;
  }

  .detail-bottom-grid {
    grid-template-columns: 1fr;
  }
}

/* ===== ROOT ===== */


:root {
    --sidebar-bg: #04163f;
    --sidebar-muted: #9fb5de;
    --sidebar-active: #1f2f50;
    --surface: #f4f7fb;
    --card: #ffffff;
    --line: #dbe2ec;
    --line-strong: #c9d2e1;
    --text: #0f172a;
    --muted: #6b7280;
    --primary: #1e40af;
}

* {
    box-sizing: border-box;
}

.sr-only {
    position: absolute;
    width: 1px;
    height: 1px;
    padding: 0;
    margin: -1px;
    overflow: visible;
    clip: rect(0, 0, 0, 0);
    border: 0;
}

body {
    margin: 0;
    font-family: "Segoe UI", Arial, Helvetica, sans-serif;
    color: var(--text);
    background: #eceff4;
}

.page-layout {
    min-height: 100vh;
    display: grid;
    grid-template-columns: 250px minmax(0, 1fr);
}

.sidebar {
    background: #00558b;
    color: #fff;
    display: flex;
    flex-direction: column;
    border-right: 1px solid #0b2558;
    position: sticky;
    top: 0;              /*  bắt buộc */
    height: 100vh;       /* để full chiều cao */
    align-self: start;   /* fix bug grid */
}

.brand-block {
    display: flex;
    flex-direction: column;
    align-items: center;
    padding: 22px 16px 18px;
    border-bottom: 1px solid #9aa0af;
}

.brand-logo {
    width: 118px;
    height: 150px;
    object-fit: cover;
    margin-bottom: 14px;
}


.student-info {
    width: 100%;
    text-align: left;
    display: flex;
    align-items: center;
    gap: 10px;
    margin-top: 8px;
    padding-top: 12px;
    position: relative;
}

.student-info::before {
    content: "";
    position: absolute;
    top: 0;
    left: -16px;
    right: -16px;
    border-top: 1px solid #9aa0af;
}

.avatar {
    width: 42px;
    height: 42px;
    border-radius: 50%;
    object-fit: cover;
    border: 2px solid rgba(255, 255, 255, 0.2);
    background: rgba(255, 255, 255, 0.08);
}

.student-info p {
    margin: 2px 0;
    font-size: 15px;
    color: var(--sidebar-muted);
}

.student-name {
    color: #f5f8ff !important;
    font-weight: 700;
    font-size: 16px;
}

.student-id {
    color: #d7e4ff !important;
}

.sidebar-nav {
    margin-top: 16px;
    display: flex;
    flex-direction: column;
    gap: 6px;
    padding: 0 12px;
}

.nav-item {
    display: flex;
    align-items: center;
    gap: 10px;
    color: #d7e4ff;
    text-decoration: none;
    padding: 10px 12px;
    border-radius: 10px;
    font-size: 15px;
    letter-spacing: 0.3px;    font-weight: 600;
    border: 1px solid transparent;
    transition: background 0.2s ease, border-color 0.2s ease;
}

.badge-count {
  margin-left: auto;
  min-width: 20px;
  height: 20px;
  padding: 0 6px;
  border-radius: 999px;
  background: #ef233c;
  color: #ffffff;
  font-size: 12px;
  font-weight: 700;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  line-height: 1;
}

.nav-icon {
    filter: grayscale(100%) brightness(1.5);
    width: 24px;
    height: 24px;
    border-radius: 7px;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    background: rgba(255, 255, 255, 0.08);
    font-size: 12px;
}

.nav-item:hover,
.nav-item.active {
    background: var(--sidebar-active);
    border-color: rgba(159, 181, 222, 0.35);
}

.logout-btn {
    margin-top: auto;
    display: block;
    color: #dce9ff;
    text-decoration: none;
    padding: 12px 20px;
    border-top: 1px solid #163364;
}

.main-content {
    padding: 0 10px 10px;
}

.main-header {
    margin-bottom: 10px;

    border-top: 0;
    /*background: #ffffff;*/
}

.school-title {
    margin: 0;
    font-size: 20px;
    font-weight: 700;
    color: #ababab;
    letter-spacing: 0.3px;
}

.main-header-top {
    background: #00558b;
    border-top: 3px solid #0c79b4;
    padding: 5px 32px;
}

.main-header-bottom {
    min-height: 58px;
    border-top: 1px solid #b8bec8;
    border-bottom: 2px solid #ccc;
    padding: 22px 0 0 5px;
}


.page-tab {
    margin: 0;
    position: relative;
    display: inline-flex;
    align-items: center;
    background: #00558b;
    color: #ffffff;
    font-size: 20px;
    font-weight: 700;
    line-height: 1;
    padding: 5px 22px;
    letter-spacing: 0.3px;
}

.page-tab::after {
    content: "";
    position: absolute;
    top: 0;
    right: -20px;

    width: 0;
    height: 0;

    border-bottom: 28px solid #7d7d7d; /*  đổi ở đây */
    border-right: 20px solid transparent;
}


.history-panel {
  min-height: calc(100vh - 20px);
  border-radius: 12px;
  display: flex;
  flex-direction: column;
  padding: 10px;
}

.toolbar {
  display: flex;
  gap: 6px;
  padding: 6px;
  border-radius: 12px;
}

.search-input,
.filter-group select {
  background: #fff;
  color: var(--text);
  border: 1px solid var(--line-strong);
  border-radius: 8px;
  height: 34px;
  padding: 0 10px;
  font-size: 14px;
}

.search-input {
  flex: 1;
}

.filter-group {
  display: flex;
  gap: 8px;
}

.filter-btn {
  height: 34px;
  border-radius: 8px;
  border: 1px solid #cbd5e1;
  background: #fff;
  color: #334155;
  font-size: 14px;
  font-weight: 600;
  padding: 0 10px;
  text-decoration: none;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
}

.filter-btn.apply {
  border-color: #2563eb;
  background: #2563eb;
  color: #fff;
}

.filter-btn.reset {
  border-color: #cbd5e1;
  background: #f8fafc;
}

.feedback-grid {
  flex: 1;
  margin-top: 10px;
  border: 1px solid var(--line-strong);
  border-radius: 12px;
  background: #f8fafc;
  padding: 12px;
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  grid-auto-rows: max-content;
  align-content: start;
  align-items: start;
  gap: 12px;
  overflow-y: auto;
}

.feedback-card {
  border: 1px solid var(--line);
  border-radius: 12px;
  background: var(--card);
  min-height: 220px;
  padding: 10px 0 0;
  display: flex;
  flex-direction: column;
  gap: 8px;
  overflow: hidden;
}

.card-head {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 8px;
  padding: 0 12px;
}

.status-pill {
  display: inline-flex;
  align-items: center;
  border-radius: 999px;
  padding: 3px 9px;
  font-size: 11px;
  font-weight: 700;
  border: 1px solid #d5dbe5;
  background: #eef2f7;
  color: #475569;
}

.status-pill.done {
  color: #0f766e;
  background: #dcfce7;
  border-color: #86efac;
}

.status-pill.processing {
  color: #1d4ed8;
  background: #dbeafe;
  border-color: #93c5fd;
}

.status-pill.waiting {
  color: #b45309;
  background: #ffedd5;
  border-color: #fdba74;
}


.status-pill.pending {
  color: #b45309;
  background: #ffedd5;
  border-color: #fdba74;
}

.status-pill.forwarding {
  color: #6b21a8;
  background: #f3e8ff;
  border-color: #e9d5ff;
}

.status-pill.approved {
  color: #1d4ed8;
  background: #dbeafe;
  border-color: #93c5fd;
}

.status-pill.rejected {
  color: #991b1b;
  background: #fee2e2;
  border-color: #fecaca;
}
.request-subject {
  margin: 0;
  padding: 0 12px;
  font-size: 16px;
  line-height: 1.2;
}

.request-description {
  margin: 0;
  color: #475569;
  line-height: 1.4;
  display: -webkit-box;
  -webkit-line-clamp: 3;
  -webkit-box-orient: vertical;
  overflow: hidden;
}

.request-meta-group {
  display: flex;
  flex-direction: column;
  gap: 4px;
  padding: 0 12px;
}

.request-meta {
  margin: 0;
  font-size: 12px;
  color: #475569;
  line-height: 1.4;
}

.request-chip {
  display: flex;
  align-items: center;
  gap: 8px;
  min-height: 28px;
  padding: 0 10px;
  border-radius: 8px;
  background: #eef2f7;
  color: #334155;
    font-size: 12.5px;
}

.meta-icon {
  font-size: 1rem;
  opacity: 0.5;
  vertical-align: middle;
  margin-right: 6px;
  filter: grayscale(1); /* Làm icon tiệp với màu chữ để sang hơn */
}

.card-footer {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-top: auto;
  border-top: 1px solid #e2e8f0;
  padding: 8px 12px;
}

.detail-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 4px;
  padding: 3px 6px;
  border-radius: 6px;
  border: 1px solid transparent;
  color: #1d4ed8;
  text-decoration: none;
  font-weight: 600;
  font-size: 12px;
}

.detail-btn::after {
  content: ">";
  font-size: 12px;
}

.detail-btn:hover {
  background: #eff6ff;
  border-color: #bfdbfe;
}

.request-date {
  color: #8ba0bd;
  font-size: 12px;
}

.request-detail {
  margin-top: 12px;
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.detail-header {
  display: flex;
}

.back-link {
  text-decoration: none;
  color: #1d4ed8;
  font-weight: 600;
}

.detail-top-card {
  border: 1px solid var(--line);
  border-radius: 12px;
  background: #fff;
  padding: 12px;
}

.detail-top-card h2 {
  margin: 0 0 12px;
    font-size: 18px;
}

.detail-top-card h3 {
  margin: 14px 0 8px;
}

.detail-meta {
  display: flex;
  gap: 8px;
  flex-wrap: wrap;
}

.detail-meta-row {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 10px;
  flex-wrap: wrap;
}

.forum-post-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  border: 1px solid #bfdbfe;
  background: #eff6ff;
  color: #1d4ed8;
  text-decoration: none;
  border-radius: 8px;
  padding: 6px 10px;
  font-size: 13px;
  font-weight: 700;
  white-space: nowrap;
}

.forum-post-btn:hover {
  background: #dbeafe;
}

.meta-chip {
  display: inline-flex;
  align-items: center;
  border-radius: 999px;
  padding: 2px 8px;
  border: 1px solid #d5dbe5;
  background: #f8fafc;
  color: #475569;
  font-size: 11px;
  font-weight: 600;
}

.meta-chip.mode-chip {
  font-weight: 700;
}

.meta-chip.mode-public {
  color: #1d4ed8;
  background: #dbeafe;
  border-color: #93c5fd;
}

.meta-chip.mode-department {
  color: #0f766e;
  background: #ecfeff;
  border-color: #67e8f9;
}

.meta-chip.time-chip {
  color: #334155;
  background: #f1f5f9;
  border-color: #cbd5e1;
}

.meta-chip.dept-chip {
  color: #92400e;
  background: #fef3c7;
  border-color: #fcd34d;
}

.detail-description {
  margin: 0;
  color: #334155;
  line-height: 1.6;
    font-size: 14px;
}

.detail-bottom-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 12px;
}

.detail-bottom-grid.single-panel {
  grid-template-columns: 1fr;
}

.detail-panel {
  border: 1px solid var(--line);
  border-radius: 12px;
  background: #fff;
  min-height: 300px;
  padding: 14px;
}

.detail-panel h3 {
  margin: 0 0 12px;
}

.timeline {
  position: relative;
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.timeline::before {
  content: "";
  position: absolute;
  left: 8px;
  top: 10px;
  bottom: 10px;
  width: 2px;
  background: #bfdbfe;
}

.timeline-item {
  position: relative;
  display: grid;
  grid-template-columns: 18px 1fr;
  gap: 10px;
  margin: 0;
}

.timeline-dot {
  width: 10px;
  height: 10px;
  border-radius: 50%;
  background: #3b82f6;
  margin-top: 8px;
}

.timeline-card {
  border: 1px solid #e2e8f0;
  border-radius: 10px;
  background: #f8fafc;
  padding: 10px;
}

.timeline-head {
  display: flex;
  justify-content: space-between;
  gap: 8px;
  align-items: center;
}

.timeline-head-left {
  display: flex;
  align-items: center;
  gap: 8px;
}

.timeline-type {
  display: inline-flex;
  align-items: center;
  border-radius: 999px;
  padding: 3px 8px;
  font-size: 11px;
  font-weight: 700;
  color: #334155;
  background: #e2e8f0;
}

.timeline-head time {
  color: #64748b;
  font-size: 12px;
}

.timeline-card p {
  margin: 8px 0 0;
  color: #334155;
}

.timeline-empty {
  border: 1px dashed #cbd5e1;
  border-radius: 10px;
  padding: 12px;
  color: #64748b;
  background: #f8fafc;
}

.chat-empty {
  min-height: 220px;
  border: 1px dashed #cbd5e1;
  border-radius: 10px;
  display: flex;
  align-items: center;
  justify-content: center;
  color: #64748b;
}

.chat-empty.compact {
  min-height: 140px;
  background: #ffffff;
}

.conversation-list {
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.conversation-item {
  width: 100%;
  border: 1px solid #d7dee8;
  border-radius: 14px;
  background: #ffffff;
  padding: 14px;
  display: grid;
  grid-template-columns: 42px minmax(0, 1fr) auto;
  gap: 12px;
  text-align: left;
  cursor: pointer;
}

.conversation-item:hover {
  border-color: #c4d4ef;
  box-shadow: 0 2px 10px rgba(59, 130, 246, 0.08);
}

.conversation-item.active {
  border-color: #3b82f6;
  box-shadow: 0 0 0 2px rgba(59, 130, 246, 0.15);
}

.conversation-item-icon {
  width: 38px;
  height: 38px;
  border-radius: 50%;
  background: #ecf1f8;
  color: #64748b;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  margin-top: 2px;
}

.conversation-item-main h4 {
  margin: 0;
  font-size: 32px;
  color: #0f172a;
  line-height: 1.25;
}

.conversation-item-main p {
  margin: 4px 0 8px;
  color: #64748b;
  font-size: 14px;
}

.conversation-item time {
  color: #7185ab;
  font-size: 13px;
  white-space: nowrap;
}

.conversation-open-pill {
  display: inline-flex;
  align-items: center;
  border-radius: 999px;
  padding: 3px 10px;
  background: #dcfce7;
  color: #166534;
  font-size: 12px;
  font-weight: 700;
}

.chat-drawer-backdrop {
  position: fixed;
  inset: 0;
  background: rgba(2, 6, 23, 0.32);
  z-index: 1200;
}

.chat-drawer {
  position: fixed;
  top: 0;
  right: -440px;
  width: 410px;
  max-width: 95vw;
  height: 100vh;
  border-left: 1px solid #e2e8f0;
  background: #ffffff;
  display: grid;
  grid-template-rows: auto 1fr auto;
  z-index: 1300;
  transition: right 0.25s ease;
}

.chat-drawer.open {
  right: 0;
}

.chat-drawer-header {
  padding: 16px;
  border-bottom: 1px solid #e2e8f0;
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
  gap: 10px;
}

.chat-drawer-header h3 {
  margin: 0;
  font-size: 34px;
  color: #0f172a;
  line-height: 1.3;
}

.chat-drawer-header p {
  margin: 6px 0 0;
  color: #64748b;
  font-size: 13px;
}

.chat-drawer-close {
  border: 0;
  background: transparent;
  color: #64748b;
  font-size: 24px;
  line-height: 1;
  cursor: pointer;
}

.chat-drawer-message-list {
  overflow-y: auto;
  padding: 14px;
  background: #f8fafc;
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.chat-drawer-compose {
  display: grid;
  grid-template-columns: 34px minmax(0, 1fr) 42px;
  gap: 8px;
  align-items: center;
  padding: 10px 12px;
  border-top: 1px solid #e2e8f0;
  background: #ffffff;
}

.chat-attach-btn {
  width: 34px;
  height: 34px;
  border: 1px solid #d7dee8;
  border-radius: 10px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  color: #64748b;
  cursor: pointer;
  user-select: none;
}

.chat-drawer-compose input[type="text"] {
  width: 100%;
  border: 1px solid #d7dee8;
  border-radius: 10px;
  height: 38px;
  padding: 0 10px;
}

.chat-send-btn {
  width: 42px;
  height: 38px;
  border: 0;
  border-radius: 10px;
  background: #3b82f6;
  color: #ffffff;
  cursor: pointer;
}

.chat-message {
  max-width: 85%;
  border: 1px solid #dbe6f3;
  border-radius: 10px;
  background: #ffffff;
  padding: 8px 10px;
}

.chat-message.mine {
  margin-left: auto;
  border-color: #bfdbfe;
  background: #eff6ff;
}

.chat-message-meta {
  display: flex;
  align-items: center;
  justify-content: flex-start;
  gap: 10px;
  font-size: 12px;
  color: #64748b;
}

.chat-message-text {
  margin: 6px 0 0;
  white-space: pre-wrap;
  line-height: 1.5;
  color: #1e293b;
}

.chat-attachment-list {
  margin: 8px 0 0;
  padding-left: 18px;
}

.chat-attachment-list a {
  color: #1d4ed8;
  text-decoration: none;
}

.chat-attachment-list a:hover {
  text-decoration: underline;
}

.chat-message-time {
  margin-top: 6px;
  font-size: 11px;
  color: rgba(100, 116, 139, 0.75);
}

.chat-message.mine .chat-message-time {
  color: rgba(59, 130, 246, 0.72);
}

.chat-image-container {
  margin-top: 8px;
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.chat-inline-image {
  max-width: 280px;
  height: auto;
  border-radius: 8px;
  box-shadow: 0 2px 8px rgba(0, 0, 0, 0.1);
  cursor: pointer;
  transition: transform 0.2s ease;
}

.chat-inline-image:hover {
  transform: scale(1.02);
}

.chat-message.mine .chat-inline-image {
  max-width: 280px;
}


.pagination {
  margin-top: 10px;
  display: flex;
  justify-content: center;
  align-items: center;
  gap: 10px;
  color: #243047;
  font-weight: 600;
    font-size: 13px;
}

.page-btn {
  width: 28px;
  height: 28px;
  border: 1px solid var(--line-strong);
  border-radius: 7px;
  color: #64748b;
  background: #fff;
  cursor: pointer;
  font-size: 12px;
  text-decoration: none;
  display: inline-flex;
  align-items: center;
  justify-content: center;

}

.page-btn:disabled {
  cursor: not-allowed;
  opacity: 0.55;
}

.empty-state {
  grid-column: 1 / -1;
  min-height: 220px;
  border: 2px dashed var(--line-strong);
  border-radius: 12px;
  background: #fff;
  display: flex;
  flex-direction: column;
  justify-content: center;
  align-items: center;
  text-align: center;
  color: #475569;
}

.empty-state h3 {
