     var escaped = false;
     for (var i = 0; i < val.length; i++) {
       var ch = val.charAt(i);
       if (escaped) {
         cur += ch;
         escaped = false;
         continue;
       }
       if (ch === '\\') {
         cur += ch;
         escaped = true;
         continue;
       }
